"""Migrated Meridian CRM 4.2 ACCT_MASTER validation rules."""

from decimal import Decimal
from typing import Any


def _value(record: dict, field: str) -> Any:
    """Return a field value, treating missing and None values as legacy empty."""
    value = record.get(field, "")
    return "" if value is None else value


def _text(record: dict, field: str) -> str:
    return str(_value(record, field))


def _numeric(value: Any) -> Decimal:
    """Apply legacy numeric-context coercion: empty values compare as zero."""
    if value is None or value == "":
        return Decimal(0)
    return Decimal(str(value))


def _error(code: str, message: str, severity: str = "BLOCK") -> dict:
    return {"code": code, "message": message, "severity": severity}


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    today: str = "20260901",
) -> list[dict]:
    """Validate an ACCT_MASTER post-write image in legacy rule-file order."""
    del today  # Present for the fixed interface; these rules do not use TODAY().

    errors: list[dict] = []
    old_record = old if event == "UPDATE" and old is not None else {}

    # ACC-001: WHEN INSERT,UPDATE
    if event in ("INSERT", "UPDATE"):
        if len(_text(record, "ACCT_NM")) < 2:
            errors.append(_error("E1001", "Account name too short"))

    # ACC-002: WHEN INSERT,UPDATE
    if event in ("INSERT", "UPDATE"):
        if _text(record, "ACCT_TYP") not in ("C", "P", "R", "X"):
            errors.append(_error("E1002", "Invalid account type"))

    # ACC-003: WHEN INSERT,UPDATE
    if event in ("INSERT", "UPDATE"):
        ann_rev = _value(record, "ANN_REV")
        if _numeric(0 if ann_rev == "" else ann_rev) < 0:
            errors.append(_error("E1003", "Annual revenue negative"))

    # ACC-004: WHEN UPDATE
    if event == "UPDATE":
        releasing_hold_with_zero_limit = (
            _text(old_record, "CRED_HOLD") == "Y"
            and _text(record, "CRED_HOLD") == "N"
            and _numeric(_value(record, "CRED_LIMIT")) <= 0
        )
        if releasing_hold_with_zero_limit:
            errors.append(
                _error(
                    "E1004",
                    "Cannot release credit hold with zero credit limit",
                )
            )

    # ACC-005: WHEN INSERT,UPDATE
    if event in ("INSERT", "UPDATE"):
        if len(_text(record, "REGION_CD")) != 3:
            errors.append(
                _error("E1005", "Region code must be 3 chars", severity="WARN")
            )

    return errors


def is_blocked(errors: list[dict]) -> bool:
    """Return whether the collected validation failures include a BLOCK error."""
    return any(error.get("severity") == "BLOCK" for error in errors)
